                16,
                16,
                "bf16",
                "f32",
                "rocdl_mfma_f32_16x16x16bf16_1k",
                VectorElemKind::BF16,
                VectorElemKind::F32,
            },
            {
                "mfma_32x32x8_bf16_f32",
                32,
